package com.yazaki.printingservice.application;
import java.time.*; import java.util.*; import jakarta.persistence.EntityManager;
import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import com.yazaki.printingservice.domain.model.*; import com.yazaki.printingservice.domain.repository.*;
@Service
public class PrintQueueWorker {
 private final EntityManager em; private final RoutingEngine routing; private final PrintAttemptRepository attempts; private final PrintEventRepository events; private final Clock clock=Clock.systemUTC();
 @Value("${printing.queue.batch-size:5}") int batchSize; @Value("${printing.queue.base-retry-delay:PT10S}") Duration baseDelay; @Value("${printing.queue.processing-timeout:PT2M}") Duration processingTimeout; @Value("${printing.queue.enabled:true}") boolean enabled;
 public PrintQueueWorker(EntityManager em,RoutingEngine routing,PrintAttemptRepository attempts,PrintEventRepository events){this.em=em;this.routing=routing;this.attempts=attempts;this.events=events;}
 @Scheduled(fixedDelayString="${printing.queue.poll-delay:2000}") @Transactional public void poll(){if(!enabled)return;var now=clock.instant();@SuppressWarnings("unchecked") List<UUID> ids=em.createNativeQuery("SELECT id FROM print_job WHERE status IN ('QUEUED','RETRY_SCHEDULED') AND (next_attempt_at IS NULL OR next_attempt_at <= :now) ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT :limit",UUID.class).setParameter("now",now).setParameter("limit",batchSize).getResultList();for(var id:ids)process(em.find(PrintJob.class,id),now);}
 @Scheduled(fixedDelayString="${printing.queue.recovery-delay:60000}") @Transactional public void recover(){if(!enabled)return;var threshold=clock.instant().minus(processingTimeout);@SuppressWarnings("unchecked") List<UUID> ids=em.createNativeQuery("SELECT id FROM print_job WHERE status='PROCESSING' AND processing_started_at < :threshold FOR UPDATE SKIP LOCKED",UUID.class).setParameter("threshold",threshold).getResultList();for(var id:ids){var j=em.find(PrintJob.class,id);retryOrFail(j,"PROCESSING_TIMEOUT","Recovered stalled processing job");}}
 private void process(PrintJob job,Instant now){job.reserve("worker-"+UUID.randomUUID(),now);event(job,PrintJobStatus.PROCESSING,"Job reserved by worker");var attempt=new PrintAttempt(job,job.getRetryCount()+1,now);attempts.save(attempt);var result=routing.route(job.getPrinter().getType()).submit(job);attempt.complete(result.result(),clock.instant(),result.errorCode(),result.message());if(result.successful()){job.transitionTo(PrintJobStatus.SUBMITTED,clock.instant(),null,null);event(job,PrintJobStatus.SUBMITTED,"Job accepted by fake adapter");}else if(result.temporary())retryOrFail(job,result.errorCode(),result.message());else{job.transitionTo(PrintJobStatus.FAILED,clock.instant(),result.errorCode(),result.message());event(job,PrintJobStatus.FAILED,result.message());}}
 private void retryOrFail(PrintJob job,String code,String message){if(job.getRetryCount()<job.getMaxRetries()){long multiplier=1L<<Math.min(job.getRetryCount(),10);job.scheduleRetry(clock.instant().plus(baseDelay.multipliedBy(multiplier)),code,message);event(job,PrintJobStatus.RETRY_SCHEDULED,message);}else{job.transitionTo(PrintJobStatus.FAILED,clock.instant(),code,message);event(job,PrintJobStatus.FAILED,message);}}
 private void event(PrintJob job,PrintJobStatus status,String message){events.save(new PrintEvent(job,events.maxSequence(job.getId())+1,status,clock.instant(),message));}
}
